<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Button, Empty, Skeleton, Tag } from 'vant'
import { httpClient } from '@/shared/http/client'
import { localTime } from '@/shared/ui/presentation'
interface Notice {kind?:string;businessNo?:string;reason?:string;id:number;caseId:string;title:string;read:boolean;createdAt:string}
interface Task {taskKey:string;caseId:string;title:string;deadline:string|null;overdue:boolean}
const route=useRoute(),router=useRouter(),notices=ref<Notice[]>([]),tasks=ref<Task[]>([]),noticeTotal=ref(0),taskTotal=ref(0),noticePage=ref(1),taskPage=ref(1),busy=ref(false),error=ref(''),message=ref('')
const tab=computed(()=>route.query.tab==='todos'?'todos':'notices')
function selectTab(value:'todos'|'notices'){if(tab.value!==value)void router.push({path:'/notifications',query:{tab:value}})}
async function load(){busy.value=true;error.value='';try{const [inbox,todo]=await Promise.all([httpClient.get<{data:{records:Notice[];total:number}}>('/notifications',{params:{page:noticePage.value,size:20}}),httpClient.get<{data:{records:Task[];total:number}}>('/notifications/todos',{params:{page:taskPage.value,size:20}})]);notices.value=inbox.data.data.records;noticeTotal.value=inbox.data.data.total;tasks.value=todo.data.data.records;taskTotal.value=todo.data.data.total}catch(e){error.value=e instanceof Error?e.message:'通知加载失败'}finally{busy.value=false}}
async function read(id:number){try{await httpClient.post(`/notifications/${id}/read`,{});message.value='已标记为已读';await load()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}}
onMounted(load)
</script>
<template>
  <section class="notifications">
    <header class="notice-head"><div><p class="eyebrow">INBOX / 站内协作</p><h1>通知与待办</h1></div><button class="refresh-button" type="button" :disabled="busy" @click="load">刷新</button></header>
    <p class="notice-help">仅显示当前账号有权访问的内容。逾期只作提示，不会自动改变案件状态。</p>
    <nav class="notice-tabs" aria-label="通知分区"><button type="button" :aria-current="tab==='todos'?'page':undefined" @click="selectTab('todos')">我的待办 <span>{{ taskTotal }}</span></button><button type="button" :aria-current="tab==='notices'?'page':undefined" @click="selectTab('notices')">站内通知 <span>{{ noticeTotal }}</span></button></nav>
    <p v-if="message" role="status">{{ message }}</p><p v-if="error" class="inline-error" role="alert">{{ error }} <Button size="small" @click="load">重试</Button></p>
    <Skeleton v-if="busy&&!tasks.length&&!notices.length" title :row="6"/>
    <section v-else-if="tab==='todos'" class="notice-panel" aria-label="我的待办"><div class="notice-heading"><div><p class="eyebrow">TODO / 待办</p><h2>当前动作</h2></div><span>{{ taskTotal }} 项</span></div><div v-if="tasks.length"><article v-for="task in tasks" :key="task.taskKey"><button class="notice-main" @click="router.push(`/work-orders/${task.caseId}`)"><span><strong>{{ task.title }}</strong><small class="mono">{{ task.deadline?`截止 ${localTime(task.deadline)}`:'不限期' }}</small></span><Tag v-if="task.overdue" plain type="warning">已逾期</Tag></button></article></div><Empty v-else image-size="64" description="当前没有待办"/><div class="pager"><Button size="small" :disabled="busy||taskPage<=1" @click="taskPage--;load()">上一页</Button><span>第 {{ taskPage }} 页 · 共 {{ taskTotal }} 项</span><Button size="small" :disabled="busy||taskPage*20>=taskTotal" @click="taskPage++;load()">下一页</Button></div></section>
    <section v-else class="notice-panel" aria-label="站内通知"><div class="notice-heading"><div><p class="eyebrow">INBOX / 通知</p><h2>站内通知</h2></div><span>{{ noticeTotal }} 条</span></div><div v-if="notices.length"><article v-for="notice in notices" :key="notice.id"><div class="notice-main"><button class="notice-copy" @click="router.push(`/work-orders/${notice.caseId}`)"><span :class="{unread:!notice.read}"></span><span><strong>{{ notice.title }}</strong><small v-if="notice.kind==='CASE_CANCELLED'">{{ notice.businessNo }} · {{ notice.reason }}</small><small>{{ localTime(notice.createdAt) }}</small></span></button><Button size="small" plain :disabled="busy||notice.read" @click="read(notice.id)">{{ notice.read?'已读':'标记已读' }}</Button></div></article></div><Empty v-else image-size="64" description="暂无站内通知"/><div class="pager"><Button size="small" :disabled="busy||noticePage<=1" @click="noticePage--;load()">上一页</Button><span>第 {{ noticePage }} 页 · 共 {{ noticeTotal }} 条</span><Button size="small" :disabled="busy||noticePage*20>=noticeTotal" @click="noticePage++;load()">下一页</Button></div></section>
  </section>
</template>
<style scoped>
.notice-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.notice-head h1{margin:3px 0;font-size:26px;line-height:1.25;letter-spacing:-.02em}.refresh-button{min-height:44px;padding:9px 14px;border:1px solid var(--color-border);border-radius:8px;background:#fff;color:var(--color-text);cursor:pointer}.refresh-button:disabled{opacity:.5}.notice-help{margin:12px 0 18px;color:var(--color-text-secondary);font-size:13px;line-height:1.65}
.notice-tabs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:0 0 14px}.notice-tabs button{min-width:0;min-height:46px;padding:8px;border:1px solid var(--color-border);border-radius:9px;background:#fff;color:var(--color-text-secondary);font:inherit;font-size:13px;cursor:pointer;transition:background-color 180ms var(--motion-fluid),color 180ms ease,transform 180ms var(--motion-fluid)}.notice-tabs button[aria-current=page]{border-color:var(--color-accent);background:var(--color-accent);color:#fff}.notice-tabs button:active{transform:scale(.97)}.notice-tabs button span{margin-left:5px;font-variant-numeric:tabular-nums}
.notice-panel{padding:18px 16px 0;border:1px solid var(--color-border);border-radius:12px;background:#fff;box-shadow:var(--shadow-surface);animation:notice-arrive 220ms var(--motion-fluid) both}.notice-heading{display:flex;align-items:end;justify-content:space-between;gap:8px;padding-bottom:12px;border-bottom:1px solid var(--color-border)}.notice-heading h2{margin:2px 0;font-size:18px}.notice-heading>span{color:var(--color-text-secondary);font-size:12px}.notice-panel article{border-bottom:1px solid var(--color-border)}
.notice-main{display:flex;width:100%;min-height:58px;align-items:center;justify-content:space-between;gap:10px;margin:0!important;padding:10px 0!important;border:0!important;background:transparent!important;text-align:left}.notice-main span,.notice-main strong,.notice-main small{display:block}.notice-main small{margin-top:4px;color:var(--color-text-secondary);font-size:12px}.notice-copy{display:flex!important;min-width:0;flex:1;align-items:center;gap:9px;margin:0!important;padding:0!important;border:0!important;background:transparent!important;text-align:left}.unread{width:7px;height:7px;flex:0 0 auto;border-radius:50%;background:#9a7624}.pager{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:14px 0;color:var(--color-text-secondary);font-size:12px}.pager :deep(.van-button){min-height:40px}
@keyframes notice-arrive{from{opacity:0;transform:translate3d(8px,0,0)}to{opacity:1;transform:translate3d(0,0,0)}}
@media(hover:hover){.notice-tabs button:hover:not([aria-current=page]),.refresh-button:hover:not(:disabled){background:var(--color-surface-muted)}}
@media(prefers-reduced-motion:reduce){.notice-tabs button,.notice-panel{animation:none;transition:none}}
</style>
